CARD = "background:rgb(255 255 255 / .04);border:1px solid rgb(255 255 255 / .07);border-radius:14px;padding:12px"

# ------------------------------------------------------------------ PIN 70 (N25/N30)
screen(pin=70, ad="Güvenlik Kontrol — 3B Bina Kesiti", yuzey="hud",
  aciklama="Koyu ekran: sol ray, güvenlik başlığı ve sekmeler, olay sayaç kartları (alarm, kapı, kamera); ortada kesit izometrik bina, kırmızı alarm odası ve uyarı etiketi; sağda kamera akışları ve olay günlüğü.",
  sahne="rgb(10 12 18)",
  css='''
.pl-s70 { width: 1080px; height: 600px; display: grid; grid-template-columns: 56px 260px 1fr 260px; background: radial-gradient(70% 80% at 55% 55%, rgb(24 30 50), rgb(8 10 16) 70%); color: var(--pl-fg-2); font-size: 10px; overflow: hidden; }
.pl-s70-rail { display: grid; align-content: start; justify-items: center; gap: 18px; padding: 18px 0; background: rgb(12 14 22); color: var(--pl-fg-3); } .pl-s70-rail .is-active { width: 32px; height: 32px; border-radius: 8px; background: rgb(60 110 255); color: white; display: grid; place-items: center; }
.pl-s70-l { padding: 18px 14px; display: grid; gap: 10px; align-content: start; } .pl-s70-l h3 { margin: 0; color: white; font-size: 18px; }
.pl-s70-k { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; } .pl-s70-k div { background: rgb(255 255 255 / .04); border: 1px solid rgb(255 255 255 / .07); border-radius: 12px; padding: 10px; display: grid; gap: 4px; } .pl-s70-k b { font-family: var(--pl-font-hud); font-size: 26px; color: white; } .pl-s70-k i { width: 22px; height: 22px; border-radius: 6px; background: var(--c); display: grid; place-items: center; font-style: normal; color: white; }
.pl-s70-k div.is-a { background: rgb(60 110 255); border-color: transparent; color: white; }
.pl-s70-scene { position: relative; }
.pl-s70-tabs { position: absolute; top: 16px; left: 10px; display: flex; gap: 4px; z-index: 2; } .pl-s70-tabs span { padding: 5px 10px; border-radius: 12px; background: rgb(255 255 255 / .05); } .pl-s70-tabs .is-active { background: rgb(60 110 255); color: white; }
.pl-s70-b { position: absolute; left: 50%; top: 56%; width: 420px; height: 300px; transform: translate(-50%, -50%) rotateX(58deg) rotateZ(-40deg); display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(3, 1fr); gap: 0; background: rgb(40 46 70); box-shadow: 0 0 0 6px rgb(60 70 100), 26px 26px 0 rgb(14 16 26); }
.pl-s70-b i { box-shadow: inset 0 0 0 3px rgb(70 80 110), 4px 4px 0 rgb(24 28 44); background: rgb(34 40 62); }
.pl-s70-b i.is-al { background: rgb(150 40 60); box-shadow: inset 0 0 0 3px rgb(255 80 100), 0 0 50px rgb(255 60 90 / .7); }
.pl-s70-b i.is-ok { background: rgb(40 70 130); }
.pl-s70-r { padding: 18px 14px; display: grid; gap: 10px; align-content: start; background: rgb(12 14 22 / .6); }
.pl-s70-cam { height: 90px; border-radius: 10px; overflow: hidden; position: relative; } .pl-s70-cam span { position: absolute; left: 6px; top: 6px; font-family: var(--pl-font-mono); font-size: 8px; color: white; background: rgb(0 0 0 / .5); padding: 1px 5px; border-radius: 3px; }
.pl-s70-log { display: grid; grid-template-columns: 8px 1fr auto; gap: 8px; align-items: center; padding: 6px 0; border-bottom: 1px solid rgb(255 255 255 / .05); } .pl-s70-log i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
''',
  html=f'''<div class="pl-s70"><nav class="pl-s70-rail"><span style="width:24px;height:24px;border-radius:50%;border:3px solid rgb(120 160 255)"></span>{I("home")}{I("user")}<span class="is-active">{I("shield")}</span>{I("camera")}{I("bar-chart")}{I("settings")}</nav>
<div class="pl-s70-l"><h3>Güvenlik</h3><span class="pl-sx-muted">Tesis · A Blok · 1. kat</span><div class="pl-s70-k">{"".join(f'<div class="{"is-a" if a else ""}"><span class="pl-sx-row"><i style="--c:{c}">{I(ic)}</i>{n}</span><b>{v}</b></div>' for c,ic,n,v,a in [("rgb(255 70 90)","alert","Alarm","2",False),("rgb(60 110 255)","lock","Kapı","48",False),("rgb(255 255 255 / .25)","camera","Kamera","36",True),("rgb(120 90 255)","users","Personel","124",False)])}</div>
<span style="color:white;font-size:12px;margin-top:6px">Ekipman özeti</span>{"".join(f'<div class="pl-sx-row" style="justify-content:space-between;padding:6px 0;border-bottom:1px solid rgb(255 255 255 / .05)"><span>{n}</span><b style="color:white;font-family:var(--pl-font-mono)">{v}</b></div>' for n,v in [("Hareket sensörü","782"),("Yangın dedektörü","214"),("Kartlı geçiş","96"),("Acil buton","38")])}</div>
<div class="pl-s70-scene"><div class="pl-s70-tabs"><span class="is-active">Genel</span><span>1. kat</span><span>2. kat</span><span>Otopark</span></div><div class="pl-s70-b">{"".join(f'<i class="{c}"></i>' for c in ["","is-ok","","","","","is-al","","is-ok","","",""])}</div>
<span class="pl-hotspot is-pulse" style="left:58%;top:44%"><span class="pl-hotspot__pin" style="--c:rgb(255 70 90)">{I("alert")}</span><span class="pl-hotspot__label">Sunucu odası · Yetkisiz giriş</span></span><span class="pl-hotspot" style="left:38%;top:60%"><span class="pl-hotspot__pin" style="--c:rgb(60 110 255)">{I("camera")}</span></span></div>
<div class="pl-s70-r"><span style="color:white;font-size:12px">Canlı kameralar</span><div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">{"".join(f'<div class="pl-s70-cam">{ph(t)}<span>KAM-{n}</span></div>' for t,n in [("night","01"),("ice","04"),("dusk","07"),("forest","12")])}</div><span style="color:white;font-size:12px;margin-top:6px">Olay günlüğü</span>{"".join(f'<div class="pl-s70-log"><i style="--c:{c}"></i><span>{t}</span><span class="pl-sx-muted">{h}</span></div>' for c,t,h in [("rgb(255 70 90)","Yetkisiz giriş · Sunucu","21:39"),("rgb(255 190 60)","Kapı açık kaldı · B12","21:22"),("rgb(60 200 120)","Devriye tamamlandı","21:00"),("rgb(60 110 255)","Kamera yeniden bağlandı","20:48")])}</div></div>''')

# ------------------------------------------------------------------ PIN 83 (N38/N54/N100)
screen(pin=83, ad="Görüntülü Görüşme — Ekip Toplantısı",
  aciklama="Koyu mor pano: sol gezinme ve takvim kartı, ortada büyük konuşmacı görüntüsü, alt kontrol düğmeleri ve katılımcı küçük resimleri; sağda katılımcı listesi ve sohbet; altta toplantı kartları.",
  sahne="linear-gradient(160deg, rgb(60 50 120), rgb(30 26 60))",
  css='''
.pl-s83 { width: 1060px; display: grid; grid-template-columns: 190px 1fr 250px; gap: 14px; padding: 16px; background: rgb(28 26 50); border-radius: 26px; color: rgb(200 196 230); font-size: 10px; }
.pl-s83-nav { display: grid; gap: 4px; align-content: start; } .pl-s83-nav b { color: white; font-size: 14px; margin-bottom: 14px; } .pl-s83-nav span { display: flex; gap: 10px; align-items: center; height: 32px; padding: 0 10px; border-radius: 10px; } .pl-s83-nav .is-active { background: rgb(120 90 255); color: white; }
.pl-s83-cal { margin-top: 20px; background: linear-gradient(160deg, rgb(150 100 255), rgb(110 70 230)); border-radius: 16px; padding: 12px; color: white; display: grid; gap: 4px; }
.pl-s83-stage { display: grid; gap: 12px; align-content: start; }
.pl-s83-video { position: relative; height: 340px; border-radius: 20px; overflow: hidden; background: linear-gradient(160deg, rgb(230 228 240), rgb(200 196 220)); }
.pl-s83-person { position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); width: 260px; height: 300px; background: radial-gradient(circle at 50% 30%, rgb(240 200 175) 0 17%, transparent 18%), radial-gradient(ellipse 34% 26% at 50% 24%, rgb(90 50 30) 0 99%, transparent 100%), radial-gradient(ellipse 50% 40% at 50% 100%, rgb(250 250 250) 0 99%, transparent 100%); }
.pl-s83-hand { position: absolute; left: 24%; top: 34%; width: 40px; height: 56px; border-radius: 20px 20px 14px 14px; background: rgb(240 200 175); transform: rotate(-12deg); }
.pl-s83-ctl { position: absolute; left: 50%; bottom: 14px; transform: translateX(-50%); display: flex; gap: 8px; padding: 6px; border-radius: 30px; background: rgb(255 255 255 / .85); }
.pl-s83-ctl span { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: rgb(255 255 255); color: rgb(40 36 70); } .pl-s83-ctl span.end { background: rgb(255 70 90); color: white; }
.pl-s83-tag { position: absolute; left: 14px; top: 14px; background: rgb(0 0 0 / .4); color: white; padding: 4px 10px; border-radius: 12px; display: flex; gap: 6px; align-items: center; } .pl-s83-tag i { width: 8px; height: 8px; border-radius: 50%; background: rgb(255 70 90); }
.pl-s83-thumbs { position: absolute; right: 14px; top: 14px; display: grid; gap: 8px; } .pl-s83-thumbs span { width: 90px; height: 60px; border-radius: 10px; overflow: hidden; display: grid; place-items: center; background: rgb(60 56 100); border: 2px solid white; }
.pl-s83-meet { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; } .pl-s83-meet div { background: rgb(255 255 255 / .05); border-radius: 14px; padding: 10px; display: grid; gap: 6px; } .pl-s83-meet b { color: white; }
.pl-s83-side { display: grid; gap: 10px; align-content: start; } .pl-s83-p { display: grid; grid-template-columns: 30px 1fr auto; gap: 8px; align-items: center; } .pl-s83-p b { color: white; display: block; } .pl-s83-p em { font-style: normal; display: flex; gap: 4px; color: rgb(150 146 190); }
.pl-s83-msg { background: rgb(255 255 255 / .05); border-radius: 12px; padding: 8px 10px; } .pl-s83-msg.me { background: rgb(120 90 255); color: white; margin-left: 30px; }
''',
  html=f'''<div class="pl-s83"><nav class="pl-s83-nav"><b>Ekip Görüşme</b>{"".join(f'<span class="{"is-active" if i==0 else ""}">{I(ic)}{n}</span>' for i,(ic,n) in enumerate([("home","Ana sayfa"),("video","Toplantılar"),("calendar","Takvim"),("message","Mesajlar"),("folder","Dosyalar"),("settings","Ayarlar")]))}<div class="pl-s83-cal"><b style="font-size:13px">Takvim</b><span>Bugün 3 toplantı</span><span style="font-size:22px;font-weight:700">14:30</span><span>Ürün sunumu</span></div></nav>
<div class="pl-s83-stage"><div class="pl-sx-row" style="color:white"><b style="font-size:15px">Ürün sunumu · PluginLabs 2.0</b><span style="flex:1"></span><span class="pl-chip" style="background:rgb(120 90 255);color:white;border:0">{I("users")}8 kişi</span><span class="pl-chip">{I("clock")}24:18</span></div>
<div class="pl-s83-video"><div class="pl-s83-person"></div><div class="pl-s83-hand"></div><span class="pl-s83-tag"><i></i>Elif · Konuşuyor</span><div class="pl-s83-thumbs">{"".join(f'<span>{face(s,46)}</span>' for s in (121,122,123))}</div><div class="pl-s83-ctl"><span>{I("mic")}</span><span>{I("video")}</span><span>{I("share")}</span><span>{I("message")}</span><span class="end">{I("phone")}</span></div></div>
<div class="pl-s83-meet">{"".join(f'<div><b>{t}</b><span>{h}</span><span class="pl-avatars">{face(s,22)}{face(s+1,22)}{face(s+2,22)}</span></div>' for t,h,s in [("Tasarım incelemesi","15:30 – 16:00",130),("Haftalık senkron","16:30 – 17:00",133),("Müşteri demosu","Yarın 10:00",136)])}</div></div>
<aside class="pl-s83-side"><span style="color:white;font-size:12px">Katılımcılar (8)</span>{"".join(f'<div class="pl-s83-p">{face(s,30)}<span><b>{n}</b>{r}</span><em>{I("mic")}{I("video")}</em></div>' for s,n,r in [(121,"Elif T.","Sunucu"),(122,"Yalçın D.","Tasarım"),(123,"Ünal S.","Satış"),(124,"İlhan K.","Geliştirme")])}
<span style="color:white;font-size:12px;margin-top:6px">Sohbet</span><div class="pl-s83-msg">Yeni komut paleti çok iyi olmuş!</div><div class="pl-s83-msg me">Teşekkürler, demo bağlantısını paylaşıyorum.</div><div class="pl-inputwrap" style="margin-top:4px">{I("message")}<input class="pl-input" placeholder="Mesaj yaz…"></div></aside></div>''')

