screen(pin=100, ad="Müzik Uygulaması — Haftalık Keşif",
  aciklama="Siyah masaüstü müzik çalar: solda kitaplık ve çalma listeleri, ortada büyük albüm kahramanı, yeşil oynat düğmesi ve parça tablosu; sağda şu an çalan ve sıradakiler; altta oynatma çubuğu.",
  sahne="rgb(248 248 248)",
  css='''
.pl-s100 { width: 1060px; height: 600px; background: rgb(0 0 0); border-radius: 10px; display: grid; grid-template-columns: 220px 1fr 240px; grid-template-rows: 1fr 64px; gap: 8px; padding: 8px; color: rgb(180 180 180); font-size: 10px; }
.pl-s100-p { background: rgb(18 18 18); border-radius: 8px; padding: 12px; overflow: hidden; display: grid; gap: 8px; align-content: start; }
.pl-s100-lib span { display: flex; gap: 10px; align-items: center; padding: 5px 0; } .pl-s100-lib span i { width: 36px; height: 36px; border-radius: 4px; overflow: hidden; flex: none; } .pl-s100-lib b { color: white; display: block; font-weight: 500; }
.pl-s100-hero { display: flex; gap: 16px; align-items: flex-end; padding: 16px; margin: -12px -12px 0; background: linear-gradient(180deg, rgb(90 60 40), rgb(18 18 18)); }
.pl-s100-cover { width: 150px; height: 150px; flex: none; box-shadow: 0 10px 30px rgb(0 0 0 / .5); position: relative; overflow: hidden; background: linear-gradient(160deg, rgb(255 120 60), rgb(160 40 80)); }
.pl-s100-cover b { position: absolute; left: 10px; bottom: 10px; color: white; font-size: 20px; font-weight: 900; line-height: .9; }
.pl-s100-hero h2 { margin: 4px 0; font-size: 46px; color: white; font-weight: 900; letter-spacing: -.03em; line-height: 1; }
.pl-s100-act { display: flex; gap: 16px; align-items: center; color: rgb(180 180 180); } .pl-s100-act .play { width: 46px; height: 46px; border-radius: 50%; background: rgb(30 215 96); color: black; display: grid; place-items: center; }
.pl-s100-tb { width: 100%; border-collapse: collapse; } .pl-s100-tb th { text-align: left; font-weight: 400; color: rgb(140 140 140); border-bottom: 1px solid rgb(255 255 255 / .1); padding: 6px; } .pl-s100-tb td { padding: 6px; } .pl-s100-tb td b { color: white; font-weight: 500; display: block; } .pl-s100-tb tr.is-on td b { color: rgb(30 215 96); }
.pl-s100-now { height: 200px; border-radius: 8px; overflow: hidden; }
.pl-s100-bar { grid-column: 1 / -1; display: grid; grid-template-columns: 260px 1fr 260px; align-items: center; padding: 0 12px; }
.pl-s100-bar .c { display: grid; justify-items: center; gap: 6px; } .pl-s100-bar .c .pl-sx-row { gap: 18px; color: white; } .pl-s100-bar .c .pl-sx-row span.m { width: 30px; height: 30px; border-radius: 50%; background: white; color: black; display: grid; place-items: center; }
.pl-s100-bar .c .sk { display: flex; align-items: center; gap: 8px; width: 100%; font-size: 9px; } .pl-s100-bar .c .sk div { flex: 1; height: 4px; border-radius: 2px; background: rgb(255 255 255 / .2); position: relative; } .pl-s100-bar .c .sk div::after { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 38%; background: white; border-radius: 2px; }
''',
  html=f'''<div class="pl-s100"><div class="pl-s100-p"><div class="pl-sx-row" style="color:white;gap:16px">{I("home")}<b>Ana sayfa</b></div><div class="pl-sx-row" style="gap:16px">{I("search")}Ara</div><div class="pl-sx-row" style="justify-content:space-between;color:white;margin-top:10px"><b>{I("book")} Kitaplığın</b>{I("plus")}</div><div class="pl-sx-row"><span class="pl-chip" style="background:rgb(255 255 255 / .1);border:0;color:white">Çalma listeleri</span><span class="pl-chip" style="background:rgb(255 255 255 / .1);border:0;color:white">Sanatçılar</span></div>
<div class="pl-s100-lib">{"".join(f'<span><i>{ph(t)}</i><span style="display:block;padding:0"><b>{n}</b>{s}</span></span>' for t,n,s in [("violet","Beğenilen şarkılar","Çalma listesi · 412"),("dusk","Haftalık keşif","PluginLabs Müzik"),("ocean","Odak akışı","Çalma listesi"),("warm","Gece sürüşü","Çalma listesi"),("forest","Lo-fi çalışma","Çalma listesi"),("red","Rock klasikleri","Çalma listesi")])}</div></div>
<div class="pl-s100-p"><div class="pl-s100-hero"><div class="pl-s100-cover"><b>Haftalık<br>Keşif</b></div><div><span>Çalma listesi</span><h2>Haftalık Keşif</h2><span>Her pazartesi yenilenen 30 şarkı · <b style="color:white">PluginLabs Müzik</b> · 1 sa 52 dk</span></div></div>
<div class="pl-s100-act"><span class="play">{I("play",20)}</span>{I("heart",20)}{I("download",20)}{I("more",20)}<span style="margin-left:auto">Liste {I("list")}</span></div>
<table class="pl-s100-tb"><tr><th>#</th><th>Başlık</th><th>Albüm</th><th>Eklenme</th><th>{I("clock")}</th></tr>{"".join(f'<tr class="{"is-on" if i==1 else ""}"><td>{i+1}</td><td><b>{a}</b>{b}</td><td>{c}</td><td>{d} gün önce</td><td>{e}</td></tr>' for i,(a,b,c,d,e) in enumerate([("Kordon Akşamı","Atlas Ekibi","Kıyı",2,"3:24"),("Gece Yolculuğu","Nova","Şehir Işıkları",2,"4:02"),("Mavi Saat","Lima","Ufuk",3,"2:58"),("Rüzgâr","Orion","Kuzey",5,"3:41"),("Sabah Kahvesi","Delta","Pazar",6,"3:10")]))}</table></div>
<div class="pl-s100-p"><b style="color:white">Şu an çalıyor</b><div class="pl-s100-now">{ph("night")}</div><b style="color:white;font-size:14px">Gece Yolculuğu</b><span>Nova</span><div style="{CARD};background:rgb(255 255 255 / .06)"><b style="color:white">Sanatçı hakkında</b><p style="margin:6px 0 0;line-height:1.5">Nova, İzmir çıkışlı elektronik müzik ikilisi. Aylık 1,2 milyon dinleyici.</p></div><b style="color:white;margin-top:6px">Sıradaki</b><span class="pl-sx-row">{face(141,30)}Mavi Saat · Lima</span></div>
<div class="pl-s100-bar"><span class="pl-sx-row"><span style="width:44px;height:44px;border-radius:4px;overflow:hidden">{ph("night")}</span><span><b style="color:white;display:block">Gece Yolculuğu</b>Nova</span><span style="color:rgb(30 215 96)">{I("check-circle")}</span></span><div class="c"><div class="pl-sx-row">{I("refresh")}{I("skip-back")}<span class="m">{I("pause")}</span>{I("skip-forward")}{I("rewind")}</div><div class="sk">1:32<div></div>4:02</div></div><span class="pl-sx-row" style="justify-content:flex-end;gap:12px">{I("mic")}{I("list")}{I("volume")}<span style="width:80px;height:4px;border-radius:2px;background:white"></span></span></div></div>''')

